CREATE TYPE "ProfessionalDocumentStatus" AS ENUM ('PENDING', 'RECEIVED', 'APPROVED', 'REJECTED', 'EXPIRED');
CREATE TABLE "DocumentRequirement" ("id" TEXT NOT NULL, "key" TEXT NOT NULL, "name" TEXT NOT NULL, "required" BOOLEAN NOT NULL DEFAULT true, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "DocumentRequirement_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProfessionalDocument" ("id" TEXT NOT NULL, "leadId" TEXT NOT NULL, "requirementId" TEXT NOT NULL, "storageKey" TEXT NOT NULL, "contentType" TEXT NOT NULL, "sizeBytes" INTEGER NOT NULL, "status" "ProfessionalDocumentStatus" NOT NULL DEFAULT 'RECEIVED', "receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ProfessionalDocument_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DocumentReview" ("id" TEXT NOT NULL, "documentId" TEXT NOT NULL, "reviewer" TEXT NOT NULL, "status" "ProfessionalDocumentStatus" NOT NULL, "reason" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "DocumentReview_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TermsVersion" ("id" TEXT NOT NULL, "version" TEXT NOT NULL, "content" TEXT NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "TermsVersion_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TermsAcceptance" ("id" TEXT NOT NULL, "leadId" TEXT NOT NULL, "termsVersionId" TEXT NOT NULL, "channel" TEXT NOT NULL, "phoneE164" TEXT, "ipAddress" TEXT, "consentId" TEXT NOT NULL, "acceptedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "TermsAcceptance_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "DocumentRequirement_key_key" ON "DocumentRequirement"("key"); CREATE INDEX "ProfessionalDocument_leadId_idx" ON "ProfessionalDocument"("leadId"); CREATE INDEX "ProfessionalDocument_requirementId_idx" ON "ProfessionalDocument"("requirementId"); CREATE INDEX "DocumentReview_documentId_idx" ON "DocumentReview"("documentId"); CREATE UNIQUE INDEX "TermsVersion_version_key" ON "TermsVersion"("version"); CREATE UNIQUE INDEX "TermsAcceptance_consentId_key" ON "TermsAcceptance"("consentId"); CREATE UNIQUE INDEX "TermsAcceptance_leadId_termsVersionId_key" ON "TermsAcceptance"("leadId", "termsVersionId"); CREATE INDEX "TermsAcceptance_leadId_idx" ON "TermsAcceptance"("leadId");
ALTER TABLE "ProfessionalDocument" ADD CONSTRAINT "ProfessionalDocument_leadId_fkey" FOREIGN KEY ("leadId") REFERENCES "RecruitmentLead"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "ProfessionalDocument" ADD CONSTRAINT "ProfessionalDocument_requirementId_fkey" FOREIGN KEY ("requirementId") REFERENCES "DocumentRequirement"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "DocumentReview" ADD CONSTRAINT "DocumentReview_documentId_fkey" FOREIGN KEY ("documentId") REFERENCES "ProfessionalDocument"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "TermsAcceptance" ADD CONSTRAINT "TermsAcceptance_leadId_fkey" FOREIGN KEY ("leadId") REFERENCES "RecruitmentLead"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "TermsAcceptance" ADD CONSTRAINT "TermsAcceptance_termsVersionId_fkey" FOREIGN KEY ("termsVersionId") REFERENCES "TermsVersion"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
